import React from "react";

export function TailwindCssButtonWavyButton() {
  return (
    <div>
    <div className="w-full h-screen flex items-center justify-center bg-gray-100 font-poppins">

        <button className="relative w-[250px] h-[60px] bg-yellow-400 border border-black rounded-[5mm] shadow-[3px_3px_0_rgb(0,0,0)] cursor-pointer overflow-hidden transition-shadow duration-300 hover[6px_6px_0_rgb(0,0,0)] hover10">

        <div className="relative z-10 flex items-center justify-center h-full text-xl font-bold text-black font-poppins">
          HOVER ME!
        </div>

        <div className="absolute w-full h-1/2 top-full left-0 wave"></div>
      </button>
    </div>
    </div>
  );
}
